#!/usr/bin/env python3
"""
Extract receipt data (date and total amount) from scanned images using OCR.
"""

import os
import re
from pathlib import Path
from datetime import datetime
from PIL import Image
import pytesseract
import pandas as pd
from openpyxl import Workbook
from openpyxl.utils.dataframe import dataframe_to_rows


def extract_text_from_image(image_path):
    """Extract text from image using Tesseract OCR."""
    try:
        img = Image.open(image_path)
        text = pytesseract.image_to_string(img)
        return text
    except Exception as e:
        print(f"Error processing {image_path}: {e}")
        return ""


def parse_date(text):
    """Extract date from OCR text and return in YYYY-MM-DD format."""
    # Common date patterns to look for
    patterns = [
        r'(\d{1,2}[/-]\d{1,2}[/-]\d{4})',  # DD/MM/YYYY or MM/DD/YYYY
        r'(\d{4}[/-]\d{1,2}[/-]\d{1,2})',  # YYYY/MM/DD
        r'(\d{1,2}[/-]\d{1,2}[/-]\d{2})',  # DD/MM/YY
        r'Date[:\s]+(\d{1,2}[/-]\d{1,2}[/-]\d{4})',  # Date: DD/MM/YYYY
        r'(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{4})',  # 1 Jan 2024
    ]

    for pattern in patterns:
        matches = re.findall(pattern, text, re.IGNORECASE)
        if matches:
            for match in matches:
                try:
                    # Try various date formats
                    for fmt in ['%d/%m/%Y', '%m/%d/%Y', '%Y/%m/%d', '%d/%m/%y', '%d %b %Y', '%d %B %Y']:
                        try:
                            date_obj = datetime.strptime(match.strip(), fmt)
                            return date_obj.strftime('%Y-%m-%d')
                        except ValueError:
                            continue
                except Exception:
                    continue

    return None


def extract_amount(text):
    """Extract total amount from OCR text."""
    # Split text into lines for processing
    lines = text.split('\n')

    # Keywords in priority order
    high_priority_keywords = [
        ('GRAND TOTAL', [r'GRAND\s+TOTAL']),
        ('TOTAL RM', [r'TOTAL\s+RM', r'TOTAL:\s+RM']),
        ('TOTAL AMOUNT', [r'TOTAL\s+AMOUNT']),
        ('GENERAL', [r'TOTAL', r'AMOUNT', r'TOTAL\s+DUE', r'AMOUNT\s+DUE', r'BALANCE\s+DUE', r'NETT\s+TOTAL', r'NET\s+TOTAL']),
    ]

    # Exclusion keywords
    exclusion_keywords = [
        r'SUBTOTAL', r'SUB\s+TOTAL', r'TAX', r'GST', r'SST',
        r'DISCOUNT', r'CHANGE', r'CASH\s+TENDERED'
    ]

    def has_exclusion_keyword(line):
        """Check if line contains exclusion keywords."""
        for keyword in exclusion_keywords:
            if re.search(keyword, line, re.IGNORECASE):
                return True
        return False

    # Process each priority level
    for priority_name, keyword_patterns in high_priority_keywords:
        for i, line in enumerate(lines):
            if has_exclusion_keyword(line):
                continue

            # Check if any keyword pattern matches
            matches_keyword = any(re.search(pattern, line, re.IGNORECASE) for pattern in keyword_patterns)

            if matches_keyword:
                # Try to extract number from the same line
                amount_match = re.search(r'[\d,]+\.?\d*', line)
                if amount_match:
                    amount_str = amount_match.group(0).replace(',', '')
                    try:
                        amount = float(amount_str)
                        return format_amount(amount)
                    except ValueError:
                        pass

                # If no amount on the same line, try next line
                if i + 1 < len(lines):
                    next_line = lines[i + 1]
                    amount_match = re.search(r'[\d,]+\.?\d*', next_line)
                    if amount_match:
                        amount_str = amount_match.group(0).replace(',', '')
                        try:
                            amount = float(amount_str)
                            return format_amount(amount)
                        except ValueError:
                            pass

    return None


def format_amount(amount):
    """Format amount as string with exactly two decimal places."""
    return f"{float(amount):.2f}"


def process_receipts(image_dir, output_file):
    """Process all receipt images and create Excel file."""
    image_dir = Path(image_dir)

    # Get all jpg files
    image_files = sorted([f for f in image_dir.glob('*.jpg')])

    results = []

    for image_file in image_files:
        filename = image_file.name
        print(f"Processing {filename}...")

        # Extract text from image
        text = extract_text_from_image(image_file)

        # Extract date
        date = parse_date(text)

        # Extract total amount
        total_amount = extract_amount(text)

        results.append({
            'filename': filename,
            'date': date,
            'total_amount': total_amount
        })

        # Debug output
        if date or total_amount:
            print(f"  Date: {date}, Amount: {total_amount}")
        else:
            print(f"  No data extracted")

    # Create DataFrame
    df = pd.DataFrame(results)

    # Write to Excel
    df.to_excel(output_file, sheet_name='results', index=False)
    print(f"\nExcel file created: {output_file}")


if __name__ == '__main__':
    image_dir = '/app/workspace/dataset/img'
    output_file = '/app/workspace/stat_ocr.xlsx'
    process_receipts(image_dir, output_file)

